/**
 * Presets data and models for the CSS Snippet Designer.
 * Pure data and helper functions.
 */

export interface UserSavedPreset {
	id: string;
	name: string;
	description?: string;
	savedAt: number;
	snippetFileName?: string;
	darkTokens: Record<string, string>;
	lightTokens: Record<string, string>;
	darkEnabled?: Record<string, boolean>;
	lightEnabled?: Record<string, boolean>;
	previewColors: string[];
}

export interface CuratedPreset {
	id: string;
	name: string;
	description: string;
	category: 'dark' | 'light';
	targetTheme: 'obsidian' | 'moonstone';
	previewColors: string[];
	darkTokens?: Record<string, string>;
	lightTokens?: Record<string, string>;
	/** Canvas backdrop applied alongside the palette. */
	background?: PresetBackground;
}

/**
 * A curated theme's canvas backdrop.
 *
 * Presets carry this rather than raw `--ui-bg-*` strings so a theme reads as a
 * design decision - "seigaiha in blossom pink at 22%" - instead of nine token
 * assignments, and so the picker's own vocabulary (style id, px size, 0-1
 * opacity) is the only thing an author has to get right.
 */
export interface PresetBackground {
	/** A pattern id from `BACKGROUND_PATTERN_OPTIONS`. */
	style: string;
	/** Tile size in px, as the size slider stores it. */
	size: number;
	/** 0-1, matching the opacity slider. */
	opacity: number;
	color: string;
	/** Present means two-tone; absent means a single colour. */
	color2?: string;
	scope?: 'editor' | 'workspace' | 'sidebars';
	animation?: string;
	motionAnimation?: string;
	colorAnimation?: string;
	/** Angle in degrees for two-tone gradient mode (0-360, default 135). */
	angle?: number;
}

/**
 * A per-user edit layered onto one built-in curated preset: a renamed label,
 * a rewritten description, replacement colors captured from the live
 * designer state, or both, plus the deletion list below in
 * `DesignerPluginSettings`. Kept as a sparse patch keyed by preset id -
 * rather than a full preset copy - so `effectiveCuratedPresets` can fall
 * back to whatever field the user hasn't touched.
 */
export interface CuratedPresetOverride {
	name?: string;
	description?: string;
	darkTokens?: Record<string, string>;
	lightTokens?: Record<string, string>;
	/** Explicit `null` means "no backdrop", overriding a base preset's one. */
	background?: PresetBackground | null;
	previewColors?: string[];
}

/**
 * Merges saved overrides and deletions onto the built-in curated list for
 * rendering/use, without ever mutating `base` - `CURATED_DARK_PRESETS` and
 * `CURATED_LIGHT_PRESETS` must stay exactly as authored so the invariants in
 * tests/presets.test.ts keep checking the real, original data.
 */
export function effectiveCuratedPresets(
	base: CuratedPreset[],
	overrides: Record<string, CuratedPresetOverride> | undefined,
	deletedIds: string[] | undefined
): CuratedPreset[] {
	const deleted = new Set(deletedIds ?? []);
	const ov = overrides ?? {};
	const result: CuratedPreset[] = [];
	for (const preset of base) {
		if (deleted.has(preset.id)) continue;
		const o = ov[preset.id];
		if (!o) {
			result.push(preset);
			continue;
		}
		result.push({
			...preset,
			name: o.name ?? preset.name,
			description: o.description ?? preset.description,
			darkTokens: o.darkTokens ?? preset.darkTokens,
			lightTokens: o.lightTokens ?? preset.lightTokens,
			// `null` explicitly clears a base preset's backdrop; `undefined`
			// (property absent) falls back to it.
			background: o.background !== undefined ? (o.background ?? undefined) : preset.background,
			previewColors: o.previewColors ?? preset.previewColors,
		});
	}
	return result;
}

/**
 * The canvas backdrop a preset contributes on top of its token map.
 *
 * A curated theme carries its backdrop as a design decision (`PresetBackground`)
 * so `applyPreset` can expand it into `--ui-bg-*` tokens. A user-saved preset has
 * no such field: `saveCurrentAsPreset` captures the raw `--ui-bg-*` tokens
 * directly, so its backdrop must be left exactly as the token pass applied it.
 *
 * Returns a `PresetBackground` to expand, `null` when a curated theme declares
 * it wants no backdrop (which `applyPreset` turns into an explicit
 * `--ui-bg-enabled: false`), or `undefined` for a user-saved preset, meaning
 * "the tokens already say what the background is - leave them alone".
 */
export function presetBackdrop(
	preset: CuratedPreset | UserSavedPreset
): PresetBackground | null | undefined {
	if (!('category' in preset)) return undefined;
	return preset.background ?? null;
}

/**
 * The four identity colours a preset previews - Primary Background, Secondary
 * Background, Accent Color, then Secondary Accent Color - read straight from
 * the tokens the preset applies so a swatch can never drift from the theme it
 * claims to show. `--text-accent-2` falls back to the accent exactly as
 * `applyPreset` does, and any missing token falls back to the schema default.
 *
 * Shared by the curated preview, "save current styling", and the curated
 * overwrite path so every preset previews the same four slots in the same
 * order.
 */
export function presetPaletteColors(
	tokens: Record<string, string> | Map<string, string>,
	isDark: boolean
): string[] {
	const get = (key: string): string | undefined =>
		tokens instanceof Map ? tokens.get(key) : tokens[key];
	const accent = get('--text-accent') ?? (isDark ? '#a68af9' : '#9873f7');
	return [
		get('--background-primary') ?? (isDark ? '#1e1e1e' : '#ffffff'),
		get('--background-secondary') ?? (isDark ? '#262626' : '#f6f6f6'),
		accent,
		get('--text-accent-2') ?? accent,
	];
}

/**
 * The colours a preset card previews (the top accent band and the footer
 * circles).
 *
 * A curated preset derives them from its own tokens, so it previews exactly
 * the colours it applies, whatever its tokens were edited to. A user-saved
 * preset stores the captured palette itself, so it is returned untouched.
 */
export function presetPreviewColors(preset: CuratedPreset | UserSavedPreset): string[] {
	if (!('category' in preset)) return preset.previewColors;
	const isDark = preset.category === 'dark';
	const tokens = (isDark ? preset.darkTokens : preset.lightTokens) ?? {};
	return presetPaletteColors(tokens, isDark);
}

const MOTION_ANIM_SET = new Set(['rain-scroll', 'horizontal-rain-scroll', 'side-scroll', 'rotate-cw', 'rotate-ccw', 'drift', 'pulse']);
const COLOR_ANIM_SET = new Set(['rainbow-cycle', 'gradient-rotate', 'gradient-shift', 'neon-glow']);

/** Expand a preset backdrop into the `--ui-bg-*` tokens the generator reads. */
export function backgroundTokens(bg: PresetBackground): Record<string, string> {
	const motion = bg.motionAnimation ?? (bg.animation && MOTION_ANIM_SET.has(bg.animation) ? bg.animation : 'none');
	const colorAnim = bg.colorAnimation ?? (bg.animation && COLOR_ANIM_SET.has(bg.animation) ? bg.animation : 'none');
	const tokens: Record<string, string> = {
		'--ui-bg-enabled': 'true',
		'--ui-bg-flipbook': 'none',
		'--ui-bg-flipbook-enabled': 'true',
		'--ui-bg-style': bg.style,
		'--ui-bg-scope': bg.scope ?? 'editor',
		'--ui-bg-size': `${bg.size}px`,
		'--ui-bg-opacity': String(bg.opacity),
		'--ui-bg-color': bg.color,
		'--ui-bg-gradient': bg.color2 ? 'true' : 'false',
		'--ui-bg-color-2': bg.color2 ?? bg.color,
		'--ui-bg-motion-animation': motion,
		'--ui-bg-color-animation': colorAnim,
		'--ui-bg-animation': bg.animation ?? (motion !== 'none' ? motion : colorAnim),
	};
	if (bg.angle !== undefined) {
		tokens['--ui-bg-gradient-angle'] = `${bg.angle}deg`;
	}
	return tokens;
}

/**
 * Inverse of {@link backgroundTokens}: read a live `--ui-bg-*` token map back
 * into a preset backdrop, so "overwrite with current styling" can save the
 * background as it looks right now instead of leaving the base preset's
 * backdrop to be re-applied over the captured tokens. Returns `null` when the
 * background is switched off, which an override stores as an explicit "no
 * backdrop" rather than falling back to the base one.
 */
export function presetBackgroundFromTokens(tokens: Map<string, string>): PresetBackground | null {
	if (tokens.get('--ui-bg-enabled') !== 'true') return null;
	const style = tokens.get('--ui-bg-style');
	const color = tokens.get('--ui-bg-color');
	if (!style || !color) return null;

	const size = parseInt(tokens.get('--ui-bg-size') ?? '', 10);
	const opacity = parseFloat(tokens.get('--ui-bg-opacity') ?? '');
	const bg: PresetBackground = {
		style,
		size: Number.isFinite(size) && size > 0 ? size : 24,
		opacity: Number.isFinite(opacity) ? opacity : 0.35,
		color,
	};

	const isGradient = tokens.get('--ui-bg-gradient') === 'true';
	const color2 = tokens.get('--ui-bg-color-2');
	if (isGradient && color2) bg.color2 = color2;

	// Keep the captured backdrop minimal, mirroring `backgroundTokens`'
	// defaults: `editor` scope and `none` animations are the implicit values.
	const scope = tokens.get('--ui-bg-scope');
	if (scope === 'workspace' || scope === 'sidebars') bg.scope = scope;

	const motion = tokens.get('--ui-bg-motion-animation');
	if (motion && motion !== 'none') bg.motionAnimation = motion;
	const colorAnim = tokens.get('--ui-bg-color-animation');
	if (colorAnim && colorAnim !== 'none') bg.colorAnimation = colorAnim;

	const angle = parseInt(tokens.get('--ui-bg-gradient-angle') ?? '', 10);
	if (isGradient && Number.isFinite(angle)) bg.angle = angle;

	return bg;
}

